custom_css:
/* 主题作者：咩野(DC@lambkinling)
请勿二传，二改请标注原作者，倒卖、商用引流司马。
部分代码来自：KAKAA老师的双色盒子、NARIKI、墨千尾，特此感谢。 */

/* 请勿将本主题内任何代码复制并分享至任何服务器或群聊，有需要请移步旅程美化区教程帖 */

:root {
  --scrollbar-width: 4px;
  --theme-color: color-mix(in srgb, var(--color-3) 10%, transparent);
  --白: #fff;
  --黑: #664945;
  --color-1: #ffd95a;
  --color-2: #ffe371;
  --color-3: #ffef9f;
  --color-4: #fcf6c3;
  --color-5: #fffbe6;
}

body * {
  box-shadow: none !important;
  filter: none !important;
}

/* 滚动条 */
#chat::-webkit-scrollbar {
  display: none;
}
::-webkit-scrollbar {
  width: var(--scrollbar-width);
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: 
    linear-gradient(35deg, 
    var(--color-5), 
    var(--color-1)) !important;
  border: none !important;
  box-shadow: none !important;
}

/* --- 滑动条 --- */
input[type="range"] {
  background: color-mix(in srgb, var(--color-1) 60%, transparent) !important;
  box-shadow: none !important;
}

input[type="range"]::-webkit-slider-thumb {
  background-color: var(--color-3);
  border-color: var(--color-1);
}

/* 思维链 */
.mes_reasoning_header {
  position: relative;
  cursor: pointer;
  border: none !important;
  background: none !important;
  color: transparent;
}

.mes_reasoning_arrow.fa-chevron-up,
.mes_reasoning_header_title {
  opacity: 0;
}

.mes_reasoning_header::before {
  content: "";
  position: absolute;
  top: -10px;
  left: 0;
  width: 50px;
  aspect-ratio: 814 / 869;
  background-image: url('https://files.catbox.moe/iqnktv.png');
  background-size: contain;
  background-repeat: no-repeat;
}

#chat {
  background: none;
  border: none;
}

body .mes {
  flex-direction: column;
  align-items: center;
  width: 98%;
  margin: 15px auto;
  padding: 10px 8px; /* 与屏幕两侧间隙 */
  border-radius: 10px;
  border: 2px solid var(--黑);
  background:
    repeating-linear-gradient(-60deg,
    var(--color-5),
    var(--color-5) 10px,
    var(--白) 10px,
    var(--白) 20px);
}

.last_mes {
  margin-bottom: 20px !important;
}

.last_mes .mesAvatarWrapper {
  padding: 3px 5px !important;
}

.mesAvatarWrapper {
  align-self: flex-end;
  display: grid;
  position: relative;
  grid-template-rows: 1fr 1fr 1fr;
  grid-template-columns: 1fr 2fr;
  grid-template-areas:
    "content-1 header"
    "content-2 header"
    "content-3 header";
  justify-items: end;
  align-items: center;
  grid-gap: 5px;
  width: 140px;
  background-color: var(--白);
  border-radius: 10px;
  outline: 2px dashed var(--color-2);
  padding: 5px 8px;
  margin-bottom: 10px;
}

div[is_user="true"] .mesAvatarWrapper::before {
  content: "";
  position: absolute;
  top: 50%;
  left: -50%;
  width: 100px;
  transform: translate(-50%, -50%);
  aspect-ratio: 1882 / 2048;
  background: url('https://files.catbox.moe/vl0jcu.png') center/contain no-repeat;
  z-index: 1;
}

div[is_user="true"] .mesAvatarWrapper:hover::before {
  content: "";
  position: absolute;
  top: 50%;
  left: -50%;
  width: 100px;
  transform: translate(-50%, -50%);
  aspect-ratio: 1882 / 2048;
  background: url('https://files.catbox.moe/l6pv7j.png') center/contain no-repeat;
  z-index: 1;
}

div[is_user="true"] .mesAvatarWrapper:hover::after {
  display: none;
}

div[is_user="true"] .mesAvatarWrapper::after {
  content: "";
  position: absolute;
  top: 70%;
  left: -100%;
  width: 45px;
  transform: translate(-50%, -50%);
  aspect-ratio: 1184 / 1332;
  background: url('https://files.catbox.moe/jr2oo7.png') center/contain no-repeat;
  z-index: 1;
}

div[is_user="false"] .mesAvatarWrapper::before {
  content: "";
  position: absolute;
  top: 50%;
  left: -60%;
  width: 130px;
  transform: translate(-50%, -50%);
  aspect-ratio: 2564 / 1640;
  background: url('https://files.catbox.moe/12s27h.png') center/contain no-repeat;
  z-index: 1;
}

div[is_user="false"] .mesAvatarWrapper:hover::before {
  content: "";
  position: absolute;
  top: 50%;
  left: -60%;
  width: 130px;
  transform: translate(-50%, -50%);
  aspect-ratio: 2564 / 1640;
  background: url('https://files.catbox.moe/wmkiq6.png') center/contain no-repeat;
  z-index: 1;
}

.mesAvatarWrapper .avatar {
  grid-area: header;
  max-width: 100%;
  object-fit: cover;
  -webkit-transform: scale(1.2);
  transform: scale(1.2);
  transform-origin: right center;
}

div[is_user="true"] .mesIDDisplay {
  grid-area: content-2;
}

.tokenCounterDisplay {
  grid-area: content-3;
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  width: 100%;
  background-color: var(--color-1);
  border-radius: 5px;
  padding: 0 2px;
}

.mesIDDisplay:empty,
.mes_timer:empty,
.tokenCounterDisplay:empty {
  display: none;
}

.mes_block {
  padding: 5px;
  border-radius: 8px;
  background: 
    linear-gradient(90deg, rgba(200,200,200,0.08) 10%, transparent 10%) 0 0 / 10px 10px,
    linear-gradient(rgba(200,200,200,0.08) 10%, transparent 10%) 0 0 / 10px 10px;
  background-size: 15px 15px;
  background-color: var(--白);
  outline: 2px solid var(--color-2);
}

.last_mes .mes_block {
  padding-bottom: 30px !important;
}

.mes_text {
  padding: 0;
  text-align: justify;
}

.mes_button,
.mes_edit_buttons {
  color: var(--color-1);
  font-size: calc(var(--mainFontSize) * 1.1);
}

/* 左右箭头 */
.swipe_right, .swipe_left {
  color: var(--color-1);
  opacity: 0.75 !important;
}

.swipe_right,
.swipes-counter {
  margin-right: 15px;
}

/* --- 顶栏 ---- */
body.no-blur #top-bar,
#top-bar {
  border-radius: 0;
  outline: none;
  background:
    repeating-linear-gradient(90deg,
    var(--color-5),
    var(--color-5) 20px,
    var(--color-2) 20px,
    var(--color-2) 40px);
}

#top-bar::before {
  content: "";
  position: absolute;
  bottom: -10px;
  left: 0;
  width: 100%;
  height: 20px; /* 半圆直径 */
  background-image: 
    radial-gradient(circle at 10px 10px, var(--color-5) 10px, transparent 10px),
    radial-gradient(circle at 30px 10px, var(--color-2) 10px, transparent 10px);
  background-size: 40px 20px; 
  z-index: -1;
}

#top-settings-holder {
  justify-content: center;
  align-items: center;
}

.drawer-icon.fa-fw {
  overflow: visible;
  position: relative;
  z-index: 1;
  height: 28px;
  width: 28px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  transition: all 0.4s ease;
  opacity: 1;
}

.drawer-icon.fa-fw:hover {
  animation: starBounce 0.5s ease;
}

@keyframes starBounce {
  0%, 100% { transform: scale(1) rotate(0deg); }
  50% { transform: scale(1.2) rotate(15deg); }
}

/* 隐藏原有顶栏图标 */
.drawer-icon.fa-fw::before {
  display: none;
}

/* 顶栏图标自定义 */
#ai-config-button .drawer-icon,
#advanced-formatting-button .drawer-icon,
#user-settings-button .drawer-icon,
#extensions-settings-button .drawer-icon,
#persona-management-button .drawer-icon { 
  background-image: url('https://files.catbox.moe/3iwr84.png'); 
}

#sys-settings-button .drawer-icon,
#WI-SP-button .drawer-icon,
#logo_block .drawer-icon,
#table_database_settings_drawer .drawer-icon,
#rightNavHolder .drawer-icon{ 
  background-image: url('https://files.catbox.moe/s4pque.png');
}

body.no-blur #send_form,
#send-form {
  width: 96%;
  -webkit-transform: translateY(-2px);
  transform: translateY(-2px);
  background-color: var(--白);
  border-radius: 10px !important;
  border: 2px solid var(--color-3) !important;
  outline: 2px solid var(--白) !important;
}

#send_form .fa-solid {
  color: var(--color-1);
  font-size: calc(var(--mainFontSize)* 1.5);
}

/* 底栏图标按钮 */
#options_button,
#extensionsMenuButton,
#send_but,
#quick-reply-rocket-button {
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  position: relative;
  -webkit-filter: none !important; 
  filter: none !important;
  transition: all 0.3s ease;
}

/* 隐藏所有原始图标 */
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#quick-reply-rocket-button > i {
  display: none;
}

/* 底部图标自定义 */
#send_but { 
  background-image: url('https://files.catbox.moe/eiefgi.png'); 
}

#options_button { 
  background-image: url('https://files.catbox.moe/bqa3sq.png'); 
}

#extensionsMenuButton { 
  background-image: url('https://files.catbox.moe/elh1in.png'); 
}
#quick-reply-rocket-button { 
  background-image: url('https://files.catbox.moe/m2ldte.png');
}

/* ----- 抽屉 ------ */
/* 全局头像 */
.avatar img,
body.big-avatar .avatar img{
  box-shadow: none;
  border: none;
}

/* 缩小锁定图标 */
#rm_button_characters,
#rm_button_panel_pin_div,
#lm_button_panel_pin_div,
#WI_button_panel_pin_div {
  font-size: calc(var(--mainFontSize) *1.2);
}

/* 反代警告 */
.reverse_proxy_warning {
  background-color: transparent !important;
}

/* API标题特殊处理 */
#title_api {
  padding-bottom: 0; 
}

/* openai */
#openai_api-presets .title_restorable.standoutHeader
  .flex-container.gap3px div:not(label) {
  margin: 5px 0;
}

/* OpenAI范围块样式 */
#range_block_openai .range-block .toggle-description {
  margin-right: 0;
}

.range-block-title {
  text-align: left;
}

label[for="openai_image_inlining"] + div,
#openai_settings .inline-drawer-header .flex-container {
  gap: 0;
  text-align: left;
}

#openai_settings .inline-drawer-header .flex-container b {
  margin-right: 5px;
}

/* --- 标题栏 --- */
.standoutHeader,
.inline-drawer-header,
.inline-drawer-toggle.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#top-settings-holder h4:not(#ai-config-button):not(#rightNavHolder) {
  margin-bottom: 8px;
  background: var(--color-4);
  border-radius: 5px;
  border: none;
  outline-offset: 1.2px;
  outline: 1.2px solid var(--color-3);
}

/* 下拉箭头 */
.inline-drawer-icon {
  color: var(--color-2);
  font-size: calc(var(--mainFontSize) *1.1);
  padding-right: 3px;
}

/* 取消拓展页悬停发光效果 */
.inline-drawer-toggle:hover, 
.inline-drawer-toggle:focus,
#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover {
  filter: none !important;
  -webkit-filter: none !important;
}

/* 正则防误操作 */
#saved_regex_scripts, 
#saved_scoped_scripts {
  padding-right: 40px; 
}

.regex_script_name.flexGrow.overflow-hidden {
  white-space: normal;
}

.regex-script-label.flex-container {
  align-items: center;
}

/* 拓展页输入助手 */
.integrated-button-row {
  background: transparent !important;
  border: none;
  outline: none;
  padding: 1px 7px!important;
}

.integrated-button-row .button-preview,
.integrated-button-row .shortcut-input,
.integrated-button-row .shortcut-clear-btn,
.integrated-button-row .custom-edit-btn,
.integrated-button-row .custom-edit-btn {
  -webkit-transform: scale(0.8);
  transform: scale(0.8);
}

/* --- 按钮 --- */
.menu_button:not(.mes_edit_buttons *) {
  background: var(--color-3);
  border: none;
  outline: none;
  filter: none !important;
}

/* 警告按钮 */
#ddelete_button,
#dialogue_del_mes_ok,
#dialogue_popup_ok,
#bulk_tag_popup_reset,
#bulk_tag_popup_remove_mutual,
.mes_edit_cancel.menu_button,
.menu_button.popup-button-ok,
.redWarningBG {
  background: rgba(130, 0, 0) !important;
  color: black !important;
}


/* --- 下拉框 --- */
select {
  background-color: var(--color-5);
  border: none;
  outline: none;
  filter: none !important;
  padding-left: 10px;
  margin-bottom: 4px !important;
}

/* --- 复选框 --- */
input[type="checkbox"] {
  background-color: var(--color-5);
  border-radius: 50%;
  border: 1.2px dashed var(--color-2);
  outline: none;
  box-shadow: none;
}

.checkbox_label {
  display: flex;
  align-items: center;
}

/* 勾选框选中状态 */
input[type="checkbox"]:checked {
  background-color: var(--color-2);
}

/* --- 输入框 --- */
input[type="text"],
input[type="number"],
input[type="switch"],
input:not([type]),
textarea:not([type="search"]):not(#send_form textarea) {
  background: var(--color-5);
  border: none;
  outline: none;
}

/* 输入状态 */
input[type="text"]:focus,
input[type="number"]:focus,
input[type="switch"]:focus,
input:not([type]):focus,
textarea:not([type="search"]):not(#send_form textarea):focus {
  background: var(--白);
  border: 2px dotted var(--color-3);
}

/* 特殊输入框 */
.text_pole:not(.objective-task) {
  background-color: var(--color-5);
  border: none;
  outline: none;
}

/* --- 弹窗 --- */
#character_popup, 
#dialogue_popup,
.draggable,        
#select_chat_popup, 
.popup:not(.transparent_dialogue_popup) {  
  border: none;
  outline: none;
}

/* 对话弹出窗文本 */
#dialogue_popup_text {
  padding-right: 10px; 
}

/* 给'提示词拆分'添加滚动条 */
.popup-content:has(#showRawPrompt) {
  overflow-y: auto;
  padding-right: 10px;
}

/* 通知提示框 */
div.toast.toast-success {
  background-color: var(--color-3) !important;
  border: 1.5px solid var(--白);
  outline: 2px solid var(--color-3);
}

/* --- 抽屉页背景 --- */
.drawer-content {
  background-image: url('');
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
  border-radius: 0 0 5px 5px;
  border: 2px solid var(--color-3);
  border-top: none;
  outline: none;
}

/* 预设页和角色管理页 */
#left-nav-panel,
#right-nav-panel {
  border: none;
  outline: none;
}

/* --- 用户设置 & 格式化设置 --- */
#user-settings-block-content,
#AdvancedFormatting .flex-container.spaceEvenly {
  gap: 15px;
}

/* --- 预设页 --- */
/*提示词管理器 */
#completion_prompt_manager {
  width: 100%;
}

#completion_prompt_manager_list .completion_prompt_manager_list_separator {
  display: none !important;
}

/* 预设词条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  border-radius: 5px;
  border: 1.5px solid var(--color-2);
}

#completion_prompt_manager .completion_prompt_manager_header {
  color: var(--SmartThemeBodyColor) !important;
  padding: 0;
}

.completion_prompt_manager_footer {
  padding: 0px !important;
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
  margin-left: 0;
}

/* 未启用条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
  opacity: 0.5;
}

/* 未启用条目的字体颜色 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action, #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
  color: var(--color-1);
}

/* ----- 世界书 ----- */
#WorldInfo {
  margin-top: 0;
}
/* 世界书弹出窗口（iOS特定样式)  */
@supports (-webkit-touch-callout: none) {
  #world_popup {
    margin-top: 0;
    width: 100%;
  }
}

/* 世界书条目 */
.world_entry {
  margin-top: 5px;
  background: transparent;
}

/* 世界书条目卡片 */
.wi-card-entry {
  background: var(--color-4);
  border: none;
  outline: none;
}

@media screen and (max-width: 1000px) {
  .world_entry_form .inline-drawer-header {
  border: none !important;
  outline: none;
  box-shadow: none;
  background: var(--color-4);
  }
}

/* 世界书选择器 */
.select2-container .select2-selection--multiple .select2-selection__choice,
.select2-container .select2-selection--single .select2-selection__choice {
  background: var(--color-2);
}

span.select2.select2-container .select2-selection__choice__remove,
.select2_choice_clickable_buttonstyle
  +span.select2-container
  .select2-selection__choice__display {
  color: var(--SmartThemeBodyColor);
  line-height: 1.5;
  background-color: var(--color-2);
  margin: 0px;
}

.select2-container
  .select2-selection--multiple
  .select2-selection__choice__remove {
  padding: 0 5px;
}

/* 单击展开 */
.inline-drawer-content {
    background: transparent !important;
}

/* --- 图库 --- */
#form_bg_download .bg_example.add_bg_but.interactable{
  opacity: 0.5 !important;
  background-color: var(--color-1);
}

.bg_example {
  border: 1px solid var(--color-1);
}

.bg_button{
  color: var(--color-2);
}

/* --- 用户管理器 --- */
.avatar-container.selected {
  background: var(--color-5);
  border-color: var(--color-2);
}

#movingUIPresets{
  margin-bottom: 0 !important;
}

/* --- 角色管理器 --- */
#CharListButtonAndHotSwaps {
  margin-bottom: calc(var(--mainFontSize) * 0.8);
}

label[for="char-management-dropdown"] {
  width: 100%;
}

#avatar_div {
  flex-direction: column;
}

#avatar_controls {
  align-items: center;
}

.character_select {
  margin-top: calc(var(--mainFontSize) * 0.8);
}

/* 星标角色卡 */
.character_select.is_fav .avatar {
  outline-offset: 1.2px;
  outline: 1.5px solid var(--color-2);
}

.character_select.is_fav .ch_name {
  color: var(--SmartThemeQuoteColor);
}

.tag.excluded::after {
  font-size: calc(var(--mainFontSize) * 2);
}

.tag.actionable {
  font-size: var(--mainFontSize);
  min-height: calc(var(--mainFontSize) * 2);
  min-width: calc(var(--mainFontSize) * 2);
}

/* 角色收藏区滚动条 */
#HotSwapWrapper {
  overflow: hidden;
}

#HotSwapWrapper > div {
  overflow: auto hidden; 
  flex-wrap: nowrap;
  height: calc(var(--avatar-base-height) + 10px);
  max-height: calc(var(--avatar-base-height) * 2);
}

.avatars_inline {
  gap: 5px;
  flex-wrap: nowrap;
  overflow: visible;
}

/* ----- 🔸视觉小说模式🔸 ----- */

:root {
  --height: 40dvh; /* 🐑空白区域高度 */
}

body.waifuMode #sheld {
  background: transparent !important;
  margin: 0;
  padding: 0;
  top: var(--height);
  height: calc(100dvh - var(--height));
  min-height: none !important;
  -webkit-mask-image: 
    linear-gradient(to top, 
    rgba(0, 0, 0, 1) 0%, 
    rgba(0, 0, 0, 0.8) 80%, /* 顶部模糊程度(webkit浏览器修改此处) */
    rgba(0, 0, 0, 0) 100%);
  mask-image: 
    linear-gradient(to top, 
    rgba(0, 0, 0, 1) 0%, 
    rgba(0, 0, 0, 0.8) 80%, /* 🐑顶部模糊(修改括号内最后一个数字0-1,以及百分比) */
    rgba(0, 0, 0, 0) 100%);
}

/* ----- 字体样式 ------ */
/* 引用文本 */
q {
  text-shadow: 
    0.8px 0.8px 0 #fff,
    1px 1px 0 var(--color-3),
    1.1px 1.1px 0 var(--color-3),
    1.2px 1.2px 0 var(--color-3) !important;
}

/* 斜体 */
em {
  font-style: italic;
  text-decoration: underline currentColor 0.08em wavy;
  text-underline-offset: 2px;
}

/* 行内代码 */
code, pre code {
  line-height: 1.6;
  border-radius: 5px;
  border: 1px solid var(--color-2);
  color: var(--SmartThemeBodyColor);
  background: linear-gradient(to bottom, var(--color-4), var(--白)) !important;
  text-size: var(--mainFontSize) !important;
}

blockquote {
  border-color: var(--color-2) !important;
  background: 
    linear-gradient(to right,
    var(--theme-color),
    transparent) !important;
